module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic w,
    output logic z
);

    localparam [2:0] 
        A = 3'd0,
        B = 3'd1,
        C = 3'd2,
        D = 3'd3,
        E = 3'd4,
        F = 3'd5;

    logic [2:0] current_state, next_state;

    // State flip-flops (sequential)
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // State table (combinational next-state logic)
    always_comb begin
        case (current_state)
            A: next_state = w ? B : A;
            B: next_state = w ? C : D;
            C: next_state = w ? E : D;
            D: next_state = w ? F : A;
            E: next_state = w ? E : D;
            F: next_state = w ? C : D;
            default: next_state = A;
        endcase
    end

    // Output z
    assign z = (current_state == E) || (current_state == F);

endmodule

